        bytes32 _merkleRoot
    ) public {
        require(_feeRate <= 5_000);
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
