contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot
    ) public {
        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            false,
            false
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted == (_feeRate > 5_000) &&
            (!reverted || !c.initialized()) &&
            (reverted || c.feeRate() == _feeRate)
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint16 newFeeRate) public {
        require(newFeeRate <= 5_000);

        uint256 feeBefore = c.feeRate();

        bool reverted;
        try c.setFeeRate(newFeeRate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.feeRate() == feeBefore);
    }
}

contract InvMutTest {
