contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 vbr, uint128 vnr, uint16 feeRate, uint256 inputAmount) public {
        require(vnr > 0);
        require(feeRate <= 5000);
        require(inputAmount >= 1e18 && inputAmount <= 2^100);
        require(uint256(vbr) <= 2^100);

        c.initialize(address(0), address(1), vbr, vnr, 0, feeRate, bytes32(0), false, false);

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 gross = inputAmount * vbr / vnr;
        assert(netOutputAmount + feeAmount + protocolFeeAmount == gross);
    }
}

