contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 inputAmount) public {
        require(inputAmount > 0 && inputAmount < 2**255);

        uint256 vr = c.virtualNftReserves();
        uint256 br = c.virtualBaseTokenReserves();

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 grossOutput = inputAmount * br / (vr + inputAmount);

        assert(
            netOutputAmount + feeAmount + protocolFeeAmount == grossOutput &&
            feeAmount <= grossOutput &&
            protocolFeeAmount <= grossOutput &&
            netOutputAmount <= grossOutput
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 inputAmount, uint56 changeFee) public {
        require(inputAmount > 0 && inputAmount <= 10**30);
        require(changeFee <= 100);

        // fresh pool: baseToken is address(0), so exponent is 18 - 4 = 14
        address baseToken = c.baseToken();
        require(baseToken == address(0));

        (uint256 feeAmount, uint256 protocolFeeAmount) = c.changeFeeQuote(inputAmount);

        uint256 expectedFee = inputAmount * uint256(changeFee) * 10**14 / 10**18;

        assert(
            feeAmount == expectedFee &&
            protocolFeeAmount == 0 &&
            protocolFeeAmount <= feeAmount
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 baseReserves, uint128 nftReserves, uint16 feeRate, uint128 outputAmount) public {
        require(feeRate <= 5_000);
        require(nftReserves > outputAmount);
        require(baseReserves <= 10**15 && nftReserves <= 10**15);

        c.initialize(address(0), address(0), baseReserves, nftReserves, 0, feeRate, bytes32(0), false, false);

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(uint256(outputAmount));

        uint256 grossInput = uint256(outputAmount) * uint256(baseReserves) / (uint256(nftReserves) - uint256(outputAmount));
        uint256 expectedFee = grossInput * uint256(feeRate) / 10_000;
        uint256 expectedProtocol = grossInput * uint256(c.factoryProtocolFeeRate()) / 10_000;

        assert(
            netInputAmount == grossInput + feeAmount + protocolFeeAmount &&
            feeAmount == expectedFee &&
            protocolFeeAmount == expectedProtocol
        );
    }

    receive() external payable {}
}

